create function public.review_pa28_batch3_graph() returns integer
language plpgsql security definer set search_path=pg_catalog,public as $$
declare item jsonb; reference jsonb; v uuid; source_id uuid; model_id uuid; ref_id uuid; model_name text; count_rows integer:=0;
begin
 perform pg_advisory_xact_lock(hashtextextended('review-pa28-batch3',0));
 for item in select value from jsonb_array_elements('[{"type":"AD","number":"2018-07-03","hash":"95c5247a8fe12cffc3b799aa59077ae42433bc0289eee1e45cf9543c059927e5","models":["PA-28-140","PA-28-181"],"page":6,"attachment_name":"DRS_2018-07-03.html","excerpt":"Paragraph (c), Table 1 lists PA-28-140 and PA-28-181 with distinct serial scopes. The AD addresses fuel-selector cover placards.","conditions":{"configuration":"The appendix on pages 9-10 distinguishes fuel-selector cover configurations and placard positions. The profile does not record this configuration or completed actions.","compliance":"A serial match is not a compliance finding. Required actions, prior work, approved alternatives and records require review in the full original."},"model_conditions":{"PA-28-140":{"serial_ranges":"28-20001 through 28-26946; 28-7125001 through 28-7725290."},"PA-28-181":{"serial_ranges":"28-7690001 through 28-8690056; 28-8690061 through 28-8690061; 28-8690062 through 28-8690062; 2890001 through 2890205; 2890206 through 2890231; 2843001 through 2843879."}},"references":[{"authority":"PIPER","key":"SB:1309A:2018-03-06","label":"Piper SB 1309A - March 6, 2018","page":8,"excerpt":"Paragraph (n)(2)(i) incorporates Piper Service Bulletin No. 1309A, March 6, 2018.","publisher_id":"19055","conditions":{"source_text":"The dated bulletin was retrieved through Piper''s public catalog and its first-page identity and date were visually reviewed.","publisher_url":"https://s3.amazonaws.com/pipercrm/Solution/19055/SB_1309A.pdf","publisher_sha256":"5e8a78416fc8fa7b6ee1d35fe1c4cc561c11969257c9103bffed5a3e522d2fac","publisher_reviewed_date":"2026-10-14","publisher_edition_note":"March 6, 2018 edition cited by this AD. Review the full AD and bulletin together."}},{"authority":"PIPER","key":"SB:1309:2017-10-10","label":"Piper SB 1309 - October 10, 2017","page":8,"excerpt":"Paragraph (j) allows credit for specified previous actions using SB 1309, October 10, 2017, when completed before the effective date in compliance with AD 2018-02-05.","conditions":{"reference_role":"Historical prior-action credit, subject to the AD''s conditions; this is not presented as the current required bulletin edition. The bulletin text has not been retrieved."}},{"authority":"FAA","kind":"certificate","key":"AD:2018-02-05","label":"AD 2018-02-05","relationship":"supersedes","page":6,"excerpt":"Paragraph (b) states that AD 2018-07-03 replaces AD 2018-02-05, Amendment 39-19158.","conditions":{"reference_role":"Superseded AD identified from the current AD. Its complete original has not been reviewed in this batch."}}]},{"type":"AD","number":"2010-15-10","hash":"61394f59ff418fde245470fdeaffe91be35a74cb1d80e126039107aaef5d3add","models":["PA-28-140","PA-28-181"],"page":7,"attachment_name":"DRS_2010-15-10.html","excerpt":"Paragraph (c) lists PA-28-140 and PA-28-181 with distinct serial scopes for the control-wheel shaft directive.","conditions":{"configuration":"Pilot/copilot shaft configuration, completed inspections and any required corrective actions must be evaluated from the full AD and applicable service data.","compliance":"Matching a reviewed serial range does not determine completed work or aircraft compliance."},"model_conditions":{"PA-28-140":{"serial_ranges":"28-20001 through 28-26946; 28-7125001 through 28-7725290."},"PA-28-181":{"serial_ranges":"28-7690001 through 28-8690056; 28-8690061 through 28-8690061; 28-8690062 through 28-8690062; 2890001 through 2890205; 2890206 through 2890231; 2843001 through 2843672."}},"references":[{"authority":"PIPER","key":"SB:1197A:2009-09-01","label":"Piper SB 1197A - September 1, 2009","page":10,"excerpt":"Paragraph (h) names Piper Mandatory Service Bulletin 1197A, September 1, 2009, or 1197B, May 3, 2010.","conditions":{"reference_role":"The AD names alternative editions, not two cumulative required installations. Applicable procedures and prior work still require review. The 1197A text has not been retrieved."}},{"authority":"PIPER","key":"SB:1197B:2010-05-03","label":"Piper SB 1197B - May 3, 2010","page":10,"excerpt":"Paragraph (h) names Piper Mandatory Service Bulletin 1197A, September 1, 2009, or 1197B, May 3, 2010.","publisher_id":"19038","conditions":{"reference_role":"The AD names alternative editions. The referenced 1197B PDF was retrieved through Piper''s public catalog and its date and identity were visually reviewed.","publisher_url":"https://s3.amazonaws.com/pipercrm/Solution/19038/SB_1197B_AD_ref.pdf","publisher_sha256":"431db15445511447ca581b47bd2332a727c8bed5051fc345e6c85fba270d1745","publisher_reviewed_date":"2026-10-14","publisher_edition_note":"AD-cited May 3, 2010 edition. Piper''s catalog also lists 1197E; this link does not substitute a later bulletin for the edition named in the AD."}}]},{"type":"AD","number":"2005-19-20","hash":"1eb8cb9958670793cb6408dca35c5ff3de5be7ac7ac2a7b01a7795f9871e7499","models":["PA-28-181"],"page":5,"attachment_name":"DRS_2005-19-20.html","excerpt":"Paragraph (c) includes PA-28-181 within the stated serial scope and requires both an SA2660CE installation between April 20, 1998 and April 1, 2005, and incorporation of Petersen SB98-1.","conditions":{"serial_scope":"The paragraph gives combined model serial ranges and an open-ended remainder. No standalone automatic serial rule is derived here.","installation_window":"SA2660CE installed between April 20, 1998 and April 1, 2005, together with incorporation of SB98-1. A user-reported installed STC alone does not establish these conditions.","compliance":"Installation dates, incorporated service changes, required actions and completed work are not established by the browser profile."},"references":[{"authority":"FAA","kind":"certificate","key":"STC:SA2660CE","label":"STC SA2660CE","page":5,"excerpt":"Paragraph (c)(2) identifies STC SA2660CE installed between April 20, 1998 and April 1, 2005 as an applicability condition.","conditions":{"reference_role":"Conditional installation predicate; this relationship does not assert that the STC is installed on an aircraft."}},{"authority":"PETERSEN","key":"SB:98-1:UNDATED","label":"Petersen SB98-1 - date not stated in AD","page":5,"excerpt":"Paragraph (c)(3) requires incorporation of Petersen Service Bulletin SB98-1 as a further applicability condition.","conditions":{"source_text":"The reference is verified in the AD. The bulletin date and full text have not been retrieved."}},{"authority":"PETERSEN","key":"SB:05-2:2005-04-12","label":"Petersen SB 05-2 - April 12, 2005","page":6,"excerpt":"Paragraph (g) incorporates Petersen Service Bulletin PA-28-160, -161, -180, -181, Bulletin No. SB 05-2, April 12, 2005.","conditions":{"source_text":"The reference is verified in the AD. The manufacturer bulletin text has not been retrieved."}}]},{"type":"STC","number":"SA2660CE","hash":"b99c31b1cbf6f44e750060498fb227f579aeb713ee4971b4ec73e54f85a8a888","models":["PA-28-181"],"page":3,"excerpt":"The continuation''s item 6 explicitly lists PA-28-181 Archer III, with serial and electrical-system limitations. Page 1 identifies type certificate 2A13 and additional installation conditions.","conditions":{"installation":"Not confirmed on an individual aircraft. Engine conversion, fuel-system configuration, installer compatibility, written holder permission and permanent records must be verified from page 1.","serial_scope":"Use the original page 3 table. No automatic STC serial rule is derived. Item 4 prints ''PA-181'' for Archer II; this review does not silently normalize that entry or extend item 6''s scope.","engine_condition":"Page 1 requires an engine modified under SE2563CE OR SE2587CE; these are alternatives, not a requirement to install both.","fuel_system":"Page 1 excludes fuel manifold/reservoir installations and requires a 3/8-inch RH fuel supply line used for takeoff and landing."},"references":[{"authority":"FAA","kind":"certificate","key":"STC:SE2563CE","label":"STC SE2563CE","page":1,"excerpt":"Limitation 1 requires an engine modified in accordance with STC SE2563CE or SE2587CE.","conditions":{"reference_role":"Alternative engine approval: SE2563CE OR SE2587CE. The engine certificate original and individual installation have not been verified."}},{"authority":"FAA","kind":"certificate","key":"STC:SE2587CE","label":"STC SE2587CE","page":1,"excerpt":"Limitation 1 requires an engine modified in accordance with STC SE2563CE or SE2587CE.","conditions":{"reference_role":"Alternative engine approval: SE2563CE OR SE2587CE. The engine certificate original and individual installation have not been verified."}},{"authority":"PETERSEN","key":"DRAWING-LIST:28-TL-2:D:1990-09-13","label":"Petersen drawing list 28-TL-2 rev D - September 13, 1990","page":1,"excerpt":"Data Required item 2 identifies Drawing List 28-TL-2, revision D, September 13, 1990, or later FAA-approved revision.","conditions":{"source_text":"The reference is verified in the certificate; the design-data document has not been retrieved."}},{"authority":"PETERSEN","key":"DRAWING-LIST:28-TL-3:H:1990-10-16","label":"Petersen drawing list 28-TL-3 rev H - October 16, 1990","page":1,"excerpt":"Data Required item 3 identifies Drawing List 28-TL-3, revision H, October 16, 1990, or later FAA-approved revision.","conditions":{"source_text":"The reference is verified in the certificate; the design-data document has not been retrieved."}},{"authority":"PETERSEN","key":"AFMS:2:BASE:1990-10-17","label":"Petersen AFM supplement 2 - October 17, 1990","page":1,"excerpt":"Data Required item 4 identifies Airplane Flight Manual Supplement No. 2, revision (-), October 17, 1990, or later FAA-approved revision.","conditions":{"source_text":"The reference is verified in the certificate; the supplement text has not been retrieved."}}]}]'::jsonb) loop
  select dv.id into v from public.document_versions dv join public.documents d on d.id=dv.document_id
   where d.authority='FAA' and d.document_type=item->>'type' and d.document_number=item->>'number' and dv.content_sha256=item->>'hash'
    and dv.status='current' and dv.is_published and d.is_published and exists(select 1 from public.related_document_matches match where match.version_id=dv.id and match.is_active) limit 1;
  if v is null then raise exception 'Verified current original missing'; end if;
  insert into public.catalog_entities(authority,entity_type,natural_key,label,is_published) values('FAA','certificate',(item->>'type')||':'||(item->>'number'),(item->>'type')||' '||(item->>'number'),true)
   on conflict(authority,entity_type,natural_key) do update set is_published=true returning id into source_id;
  for model_name in select jsonb_array_elements_text(item->'models') loop
   select id into model_id from public.catalog_entities where authority='FAA' and entity_type='aircraft_model' and natural_key=model_name;
   if model_id is null or not exists(select 1 from public.related_document_matches where version_id=v and model=model_name and is_active) then raise exception 'Current model index missing'; end if;
   insert into public.relationships(source_entity_id,target_entity_id,relationship_type,evidence_version_id,evidence_page,evidence_excerpt,applicability_conditions,review_status,is_published)
    select source_id,model_id,case item->>'type' when 'AD' then 'applies_to' else 'approved_for' end,v,(item->>'page')::integer,item->>'excerpt',(item->'conditions')||coalesce(item->'model_conditions'->model_name,'{}'::jsonb),'reviewed',true
    where not exists(select 1 from public.relationships where source_entity_id=source_id and target_entity_id=model_id and evidence_version_id=v);
   count_rows:=count_rows+1;
  end loop;
  for reference in select value from jsonb_array_elements(item->'references') loop
   insert into public.catalog_entities(authority,entity_type,natural_key,label,is_published)
    values(reference->>'authority',coalesce(reference->>'kind','service_document'),reference->>'key',reference->>'label',true)
    on conflict(authority,entity_type,natural_key) do update set is_published=true returning id into ref_id;
   insert into public.relationships(source_entity_id,target_entity_id,relationship_type,evidence_version_id,evidence_page,evidence_excerpt,applicability_conditions,review_status,is_published)
    select source_id,ref_id,coalesce(reference->>'relationship','references'),v,(reference->>'page')::integer,reference->>'excerpt',reference->'conditions','reviewed',true
    where not exists(select 1 from public.relationships where source_entity_id=source_id and target_entity_id=ref_id and evidence_version_id=v and relationship_type=coalesce(reference->>'relationship','references'));
   count_rows:=count_rows+1;
  end loop;
 end loop;
 return count_rows;
end $$;
revoke all on function public.review_pa28_batch3_graph() from public,anon,authenticated;
grant execute on function public.review_pa28_batch3_graph() to service_role;

create or replace view public.model_graph with(security_invoker=true) as
select r.id,d.document_number as tcds_number,s.label as model,t.label as target,t.entity_type as target_type,
  r.relationship_type,r.evidence_page,r.evidence_excerpt,r.applicability_conditions,v.revision_label as evidence_revision,v.source_url,
  d.document_number as source_document_number,d.document_type as source_document_type,t.natural_key as basis_key,
  null::text as path_via,'outgoing'::text as direction,v.id as evidence_version_id,
  s.id as source_entity_id,t.id as target_entity_id,s.id as model_entity_id,null::uuid as via_entity_id,r.evidence_attachment_id,a.file_name as evidence_file_name,v.metadata->>'original_source_url' as original_source_url
from public.relationships r join public.catalog_entities s on s.id=r.source_entity_id join public.catalog_entities t on t.id=r.target_entity_id
join public.document_versions v on v.id=r.evidence_version_id join public.documents d on d.id=v.document_id left join public.source_attachments a on a.id=r.evidence_attachment_id
where r.review_status='reviewed' and r.is_published and v.is_published and d.is_published and s.is_published and t.is_published and s.entity_type='aircraft_model' and d.authority='FAA' and d.document_type='TCDS' and v.id=d.current_version_id and (r.evidence_attachment_id is null or a.is_active)
union all
select r.id,'2A13',t.label,s.label,s.entity_type,r.relationship_type,r.evidence_page,r.evidence_excerpt,r.applicability_conditions,v.revision_label,v.source_url,
  d.document_number,d.document_type,s.natural_key,null::text,'incoming'::text,v.id,s.id,t.id,t.id,null::uuid,r.evidence_attachment_id,a.file_name,v.metadata->>'original_source_url'
from public.relationships r join public.catalog_entities s on s.id=r.source_entity_id join public.catalog_entities t on t.id=r.target_entity_id
join public.document_versions v on v.id=r.evidence_version_id join public.documents d on d.id=v.document_id left join public.source_attachments a on a.id=r.evidence_attachment_id
where r.review_status='reviewed' and r.is_published and v.is_published and d.is_published and s.is_published and t.is_published and t.entity_type='aircraft_model' and d.authority='FAA' and d.document_type in('AD','STC') and v.status='current' and (r.evidence_attachment_id is null or a.is_active)
  and exists(select 1 from public.related_document_matches m where m.version_id=v.id and m.model=t.label and m.is_active)
union all
select r.id,'2A13',m.label,t.label,t.entity_type,r.relationship_type,r.evidence_page,r.evidence_excerpt,r.applicability_conditions,v.revision_label,v.source_url,
  d.document_number,d.document_type,t.natural_key,s.label,'outgoing'::text,v.id,s.id,t.id,m.id,s.id,r.evidence_attachment_id,a.file_name,v.metadata->>'original_source_url'
from public.relationships r join public.catalog_entities s on s.id=r.source_entity_id join public.catalog_entities t on t.id=r.target_entity_id
join public.document_versions v on v.id=r.evidence_version_id join public.documents d on d.id=v.document_id left join public.source_attachments a on a.id=r.evidence_attachment_id
join public.relationships scope on scope.source_entity_id=s.id and scope.evidence_version_id=v.id and scope.relationship_type in('applies_to','approved_for')
join public.catalog_entities m on m.id=scope.target_entity_id and m.entity_type='aircraft_model'
where r.review_status='reviewed' and r.is_published and v.is_published and d.is_published and s.is_published and t.is_published and scope.review_status='reviewed' and scope.is_published and m.is_published and r.relationship_type in('references','supersedes') and d.authority='FAA' and d.document_type in('AD','STC') and v.status='current' and (r.evidence_attachment_id is null or a.is_active)
  and (scope.evidence_attachment_id is null or exists(select 1 from public.source_attachments sa where sa.id=scope.evidence_attachment_id and sa.is_active))
  and exists(select 1 from public.related_document_matches active where active.version_id=v.id and active.model=m.label and active.is_active);
